import re
from thefuck.shells import shell
from thefuck.specific.git import git_support


@git_support
def match(command):
    err = command.stderr
    return ('did not match any file(s) known to git.' in err
            and "Did you forget to 'git add'?" in err)


@git_support
def get_new_command(command):
    pattern = (r"error: pathspec '([^']*)' "
               r"did not match any file\(s\) known to git.")
    unmatched_path = re.findall(pattern, command.stderr)[0]

    template = shell.and_('git add -- {}', '{}')
    return template.format(unmatched_path, command.script)
